P=1000000007; N=12; g=25

def parts(n,lo=1,allowed=None):
 if n==0: yield ()
 for a in range(lo,n+1):
  if allowed is None or allowed(a):
   for b in parts(n-a,a,allowed): yield (a,)+b

def conv(a,b):
 c=[0]*(N+1)
 for i,x in enumerate(a):
  for j,y in enumerate(b[:N+1-i]): c[i+j]=(c[i+j]+x*y)%P
 return c
A=[math.factorial(6*n)//math.factorial(3*n)//math.factorial(2*n)%P for n in range(N+1)]
B=[a*(6*n+1)*pow(6*n-1,-1,P)%P for n,a in enumerate(A)]
Ai=[1]+[0]*N
for n in range(1,N+1): Ai[n]=-sum(A[i]*Ai[n-i] for i in range(1,n+1))%P
D=conv(B,Ai)
Dp=[[1]+[0]*N]
for k in range(1,11): Dp.append(conv(Dp[-1],D))
LA=[0]*(N+1)
for n in range(1,N+1): LA[n]=(A[n]-sum(i*LA[i]*A[n-i] for i in range(1,n))*pow(n,-1,P))%P
# polynomials map partition tuple to coefficient; tuple sum is T-degree
F0={p:1 for n in range(N+1) for p in parts(n)}
from collections import Counter
for p in F0:
 v=1
 for a,m in Counter(p).items(): v=v*pow(-LA[a],m,P)*pow(math.factorial(m),-1,P)%P
 F0[p]=v
sigmas=[s for n in range(11) for s in parts(n,allowed=lambda a:a%3!=2)]
gamma={}
for s in sigmas[1:]:
 l=len(s); shift=sum(a//3 for a in s); b=sum(a%3==1 for a in s)
 fac=(-1)**(l+1)*math.factorial(l-1)
 for m in Counter(s).values(): fac=fac*pow(math.factorial(m),-1,P)%P
 ar=[0]*(N+1)
 for n in range(shift,N+1): ar[n]=fac*Dp[b][n-shift]%P
 gamma[s]=ar
F={():F0}
for s in sigmas[1:]:
 counts=Counter(s); j=s[0]; out={}
 for tau in sigmas[1:]:
  tc=Counter(tau)
  if tc[j]==0 or any(v>counts[k] for k,v in tc.items()):continue
  rem=tuple(sorted((counts-tc).elements())); pol=F[rem]; ar=gamma[tau]
  for mon,c in pol.items():
   deg=sum(mon)
   for n in range(N+1-deg):
    if not ar[n]:continue
    dest=tuple(sorted(mon+(n,))) if n else mon
    x=c*ar[n]*tc[j]*(48 if n==0 else 1)
    out[dest]=(out.get(dest,0)-x)%P
 inv=pow(counts[j],-1,P)
 F[s]={m:c*inv%P for m,c in out.items() if c}
mons=list(parts(N)); ix={m:i for i,m in enumerate(mons)}
rows=[]; labels=[]
for r in range(1,N+1):
 for s in sigmas:
  if g-1+sum(s)>=3*r or (g-r-sum(s)-1)%2: continue
  pol={m:c for m,c in F[s].items() if sum(m)==r}
  for mul in parts(N-r):
   row=[0]*len(mons)
   for m,c in pol.items(): row[ix[tuple(sorted(m+mul))]]=c
   rows.append(row); labels.append([r,list(s),list(mul)])
print('monomials',len(mons),'relations',len(rows))
def rank(rows):
 basis={}; selected=[]
 for k,row0 in enumerate(rows):
  row=row0[:]
  for j in range(len(row)):
   if not row[j]:continue
   if j in basis:
    c=row[j]; row=[(a-c*b)%P for a,b in zip(row,basis[j])]
   else:
    inv=pow(row[j],-1,P);basis[j]=[a*inv%P for a in row];selected.append(k);break
 return len(basis),selected
rk,sel=rank(rows)
print('rank',rk,'dimension',len(mons)-rk,'selected labels',[labels[k] for k in sel])
os.makedirs('workspace',exist_ok=True)
json.dump({'prime':P,'monomials':mons,'rows':rows,'labels':labels,'selected':sel},open('workspace/agent2_fz25.json','w'))

