    rows=[];labels=[]
    for r in range(1,N+1):
        for s in sigmas:
            if 24+sum(s)>=3*r or (25-r-sum(s)-1)%2:
                continue
            for extra in partitions(N-r):
                row=[0]*len(mons)
                for mon,c in F[s].items():
                    if sum(mon)==r:
                        row[ix[tuple(sorted(mon+extra))]]=c
                rows.append(row);labels.append([r,list(s),list(extra)])
