    for i,row0 in enumerate(rows):
        row=row0[:]
        for j,c in enumerate(row):
            if not c:
                continue
            if j in basis:
                row=[(a-c*b)%P for a,b in zip(row,basis[j])]
            else:
                basis[j]=[a*pow(c,-1,P)%P for a in row]
                selected.append(i)
